import json
with open('data/fees.json') as f:
    fees = json.load(f)
print(f'Total fee rules: {len(fees)}')
# Show a few examples
for i in [0, 1, 2, 10, 50, 100]:
    print(f'\n--- Fee {i} ---')
    print(json.dumps(fees[i], indent=2))
# Check unique capture_delay values
cd = set()
for fee in fees:
    cd.add(str(fee.get('capture_delay')))
print(f'\nUnique capture_delay values: {cd}')
# Check unique account_type values
ats = set()
for fee in fees:
    at = fee.get('account_type')
    if at:
        for a in at:
            ats.add(a)
print(f'Unique account_type values: {ats}')
# Check null patterns
null_counts = {}
for fee in fees:
    for k, v in fee.items():
        if v is None or v == [] or v == '':
            null_counts[k] = null_counts.get(k, 0) + 1
print(f'\nNull/empty counts: {json.dumps(null_counts, indent=2)}')
"
